try {
  let raw = $input.item.json.response;
  raw = raw.replace(/```json\n/g, '').replace(/```/g, '').trim();
  const parsedData = JSON.parse(raw);
  return { json: parsedData };
} catch (error) {
  return { json: { referencia_proveedor: 'ERROR_' + Date.now(), tipo_activo: 'Desconocido', provincia: 'Desconocida', municipio: 'Desconocido', direccion: 'Error de parseo', precio_venta: 0 } };
}
